function validate([moves]) {
  if (typeof moves !== 'string' || moves.length < 1 || moves.length > 50) return 'moves has 1 to 50 characters.';
  if (!/^[LR_]+$/.test(moves)) return "moves may only contain 'L', 'R' and '_'.";
  return null;
}

