function furthestDistanceFromOrigin(moves) {
  let left = 0;
  let right = 0;
  let blank = 0;

  for (const move of moves) {
    if (move === 'L') {
      left++;
    } else if (move === 'R') {
      right++;
    } else {
      blank++;
    }
  }

  return Math.abs(left - right) + blank;
}

