function furthestDistanceFromOrigin(moves) {
  // Track every position that some choice of directions can reach.
  let reachable = new Set([0]);
  for (const move of moves) {
    const next = new Set();
    for (const p of reachable) {
      if (move !== 'R') next.add(p - 1);
      if (move !== 'L') next.add(p + 1);
    }
    reachable = next;
  }
  let best = 0;
  for (const p of reachable) best = Math.max(best, Math.abs(p));
  return best;
}

