function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 10);
  // Vary the mix so some strings are mostly one letter and some are mostly blanks.
  const weights = [rand(), rand(), rand() * rand()];
  const total = weights[0] + weights[1] + weights[2];
  let moves = '';
  for (let i = 0; i < n; i++) {
    const r = rand() * total;
    moves += r < weights[0] ? 'L' : r < weights[0] + weights[1] ? 'R' : '_';
  }
  return [moves];
}
